package com.example.battleshipgame.logic;
import java.io.Serializable; import java.util.*;
public class Board implements Serializable { public static final int SIZE=10; public enum Cell{WATER,SHIP,MISS,HIT} private final Cell[][] cells=new Cell[SIZE][SIZE]; private final List<Ship> ships=new ArrayList<>(); public Board(){clear();} public void clear(){for(int r=0;r<SIZE;r++)for(int c=0;c<SIZE;c++)cells[r][c]=Cell.WATER;ships.clear();} public Cell get(int r,int c){return cells[r][c];} public boolean placeShip(String name,int size,int row,int col,boolean h){if(row<0||col<0||row+(h?0:size-1)>=SIZE||col+(h?size-1:0)>=SIZE)return false;for(int i=0;i<size;i++)if(cells[row+(h?0:i)][col+(h?i:0)]!=Cell.WATER)return false;Ship s=new Ship(name,size);for(int i=0;i<size;i++){int r=row+(h?0:i),c=col+(h?i:0);cells[r][c]=Cell.SHIP;s.addCell(r,c);}ships.add(s);return true;} public void placeRandomFleet(){clear();int[]z={5,4,3,3,2};String[]n={"נושאת מטוסים","ספינת קרב","צוללת","משחתת","ספינת סיור"};Random x=new Random();for(int i=0;i<z.length;i++)while(!placeShip(n[i],z[i],x.nextInt(SIZE),x.nextInt(SIZE),x.nextBoolean())){}} public ShotResult shoot(int r,int c){if(r<0||c<0||r>=SIZE||c>=SIZE||cells[r][c]==Cell.HIT||cells[r][c]==Cell.MISS)return ShotResult.ALREADY_SHOT;if(cells[r][c]==Cell.WATER){cells[r][c]=Cell.MISS;return ShotResult.MISS;}cells[r][c]=Cell.HIT;for(Ship s:ships)if(s.contains(r,c)){s.hit();return s.isSunk()?ShotResult.SUNK:ShotResult.HIT;}return ShotResult.HIT;} public boolean allSunk(){for(Ship s:ships)if(!s.isSunk())return false;return !ships.isEmpty();} public List<Ship>getShips(){return ships;} }
